CREATE TABLE erp.tax_import_batch (
    batch_id integer NOT NULL,
    file_name text NOT NULL,
    file_format text NOT NULL,
    file_sha256 text NOT NULL,
    base_checksum text,
    jurisdiction_code character(2) NOT NULL,
    company_id smallint,
    change_summary text,
    imported_by text NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    result text NOT NULL,
    report text,
    CONSTRAINT tax_import_batch_file_format_check CHECK ((file_format = ANY (ARRAY['json'::text, 'xlsx'::text]))),
    CONSTRAINT tax_import_batch_result_check CHECK ((result = ANY (ARRAY['applied'::text, 'rejected'::text, 'bootstrap'::text])))
);


--
-- Name: tax_import_batch_batch_id_seq; Type: SEQUENCE; Schema: erp; Owner: -
--

CREATE SEQUENCE erp.tax_import_batch_batch_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: tax_import_batch_batch_id_seq; Type: SEQUENCE OWNED BY; Schema: erp; Owner: -
--

ALTER SEQUENCE erp.tax_import_batch_batch_id_seq OWNED BY erp.tax_import_batch.batch_id;


--
-- Name: tax_recalc_run; Type: TABLE; Schema: erp; Owner: -
--

CREATE TABLE erp.tax_recalc_run (
    recalc_id integer NOT NULL,
    trigger_version_id integer NOT NULL,
    company_id smallint NOT NULL,
    mode text NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    report jsonb NOT NULL,
    total_difference numeric(15,2) DEFAULT 0 NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_by text,
    confirmed_at timestamp with time zone,
    CONSTRAINT tax_recalc_run_mode_check CHECK ((mode = ANY (ARRAY['adjust_next_period'::text, 'recalculate_reopen'::text]))),
    CONSTRAINT tax_recalc_run_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'applied'::text, 'cancelled'::text])))
);


--
-- Name: tax_recalc_run_recalc_id_seq; Type: SEQUENCE; Schema: erp; Owner: -
--

CREATE SEQUENCE erp.tax_recalc_run_recalc_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


