ALTER SEQUENCE erp.tax_recalc_run_recalc_id_seq OWNED BY erp.tax_recalc_run.recalc_id;


--
-- Name: tax_rule; Type: TABLE; Schema: erp; Owner: -
--

CREATE TABLE erp.tax_rule (
    rule_id integer NOT NULL,
    jurisdiction_code character(2) NOT NULL,
    rule_code text NOT NULL,
    name_en text NOT NULL,
    name_th text,
    category text NOT NULL,
    rule_type text NOT NULL,
    is_mandatory boolean DEFAULT false NOT NULL,
    description text,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT tax_rule_category_check CHECK ((category = ANY (ARRAY['VAT'::text, 'WHT'::text, 'PIT'::text, 'SSO'::text, 'OTHER'::text]))),
    CONSTRAINT tax_rule_rule_code_check CHECK ((rule_code ~ '^[A-Z][A-Z0-9_]{1,40}$'::text)),
    CONSTRAINT tax_rule_rule_type_check CHECK ((rule_type = ANY (ARRAY['flat_rate'::text, 'rate_by_category'::text, 'rate_with_cap'::text, 'fixed_amount'::text, 'bracket_table'::text, 'threshold'::text, 'formula'::text])))
);


