--
-- Name: tax_rule_version; Type: TABLE; Schema: erp; Owner: -
--

CREATE TABLE erp.tax_rule_version (
    rule_version_id integer NOT NULL,
    rule_id integer NOT NULL,
    company_id smallint,
    version_no integer NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    pending_effective_to date,
    params jsonb NOT NULL,
    rounding text NOT NULL,
    legal_reference text,
    source_url text,
    notes text,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_by text,
    submitted_at timestamp with time zone,
    approved_at timestamp with time zone,
    import_batch_id integer,
    CONSTRAINT tax_rule_version_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT tax_rule_version_rounding_check CHECK ((rounding = ANY (ARRAY['half_up:0.01'::text, 'half_up:1'::text, 'down:0.01'::text, 'down:1'::text, 'up:1'::text, 'none'::text]))),
    CONSTRAINT tax_rule_version_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'retired'::text]))),
    CONSTRAINT tax_rule_version_version_no_check CHECK ((version_no >= 1))
);


