--
-- Name: v_ar_aging; Type: VIEW; Schema: erp; Owner: -
--

CREATE VIEW erp.v_ar_aging AS
 SELECT i.doc_no,
    p.name AS customer,
    i.doc_date,
    i.due_date,
    i.total,
    COALESCE(sum(pa.amount), (0)::numeric) AS settled,
    (i.total - COALESCE(sum(pa.amount), (0)::numeric)) AS outstanding,
    GREATEST((CURRENT_DATE - i.due_date), 0) AS days_overdue
   FROM ((erp.invoice i
     JOIN erp.partner p USING (partner_id))
     LEFT JOIN erp.payment_allocation pa USING (doc_no))
  WHERE ((i.doc_type = 'AR'::text) AND (i.status <> 'void'::text))
  GROUP BY i.doc_no, p.name, i.doc_date, i.due_date, i.total;


--
-- Name: v_income_statement; Type: VIEW; Schema: erp; Owner: -
--

CREATE VIEW erp.v_income_statement AS
 SELECT e.period_id,
    a.account_type,
    a.account_code,
    a.name_en,
    sum(
        CASE a.normal_side
            WHEN 'C'::bpchar THEN (l.credit - l.debit)
            ELSE (l.debit - l.credit)
        END) AS amount
   FROM ((erp.journal_line l
     JOIN erp.journal_entry e USING (je_no))
     JOIN erp.account a USING (account_code))
  WHERE ((e.status = 'posted'::text) AND (a.account_type = ANY (ARRAY['revenue'::text, 'expense'::text])))
  GROUP BY e.period_id, a.account_type, a.account_code, a.name_en
  ORDER BY e.period_id, a.account_type DESC, a.account_code;


--
-- Name: v_payslip; Type: VIEW; Schema: erp; Owner: -
--

CREATE VIEW erp.v_payslip AS
 SELECT pr.company_id,
    pr.run_id,
    pr.period_id,
    pr.pay_date,
    pr.status AS run_status,
    e.employee_id,
    ((e.first_name || ' '::text) || e.last_name) AS employee_name,
    e."position",
    pl.base_salary,
    pl.overtime,
    pl.commission,
    pl.allowance,
    pl.gross_pay,
    pl.sso_employee,
    pl.wht_pnd1,
    pl.other_deduction,
    pl.net_pay,
    pl.sso_employer,
    sv.version_no AS sso_rule_version,
    pv.version_no AS pnd1_rule_version,
    (pl.calc_trace ->> 'profile_status'::text) AS tax_profile
   FROM ((((erp.payroll_line pl
     JOIN erp.payroll_run pr USING (run_id))
     JOIN erp.employee e USING (employee_id))
     LEFT JOIN erp.tax_rule_version sv ON ((sv.rule_version_id = pl.sso_rule_version_id)))
     LEFT JOIN erp.tax_rule_version pv ON ((pv.rule_version_id = pl.pnd1_rule_version_id)));


--
-- Name: v_trial_balance; Type: VIEW; Schema: erp; Owner: -
--

CREATE VIEW erp.v_trial_balance AS
 SELECT a.account_code,
    a.name_en,
    a.account_type,
    sum(l.debit) AS total_debit,
    sum(l.credit) AS total_credit,
        CASE a.normal_side
            WHEN 'D'::bpchar THEN sum((l.debit - l.credit))
            ELSE sum((l.credit - l.debit))
        END AS balance
   FROM ((erp.journal_line l
     JOIN erp.journal_entry e USING (je_no))
     JOIN erp.account a USING (account_code))
  WHERE (e.status = 'posted'::text)
  GROUP BY a.account_code, a.name_en, a.account_type, a.normal_side
  ORDER BY a.account_code;


