	(27, 'tax_rule_version', '17', 'insert', NULL, '{"notes": "annual_sso and other_allowances come from the employee tax profile / payroll.", "params": {"inputs": ["monthly_income", "months_remaining", "ytd_income", "ytd_withheld", "annual_sso", "other_allowances"], "output": "monthly_wht", "expression": "max(0, round((bracket_tax(''PIT_BRACKETS'', max(0, ytd_income + monthly_income * months_remaining - capped(''PIT_EXPENSE'', ytd_income + monthly_income * months_remaining) - rule(''PIT_ALLOW_PERSONAL'', ''amount'') - annual_sso - other_allowances)) - ytd_withheld) / months_remaining, 2))"}, "status": "approved", "rule_id": 13, "rounding": "half_up:0.01", "company_id": null, "created_at": "2026-11-14T00:03:12.149662+07:00", "created_by": "system", "source_url": null, "version_no": 1, "approved_at": "2026-11-14T00:03:12.216053+07:00", "effective_to": null, "submitted_at": null, "submitted_by": null, "effective_from": "2017-01-01", "import_batch_id": 1, "legal_reference": "Revenue Code s.50(1); Revenue Dept. Order Por. 161/2560 (calculation method)", "rule_version_id": 17, "pending_effective_to": null}', 'import tax_rules_TH.json', 'system', '2026-11-14 00:03:12.149662+07'),
