INSERT INTO erp.tax_rule VALUES
	(1, 'TH', 'VAT_STD', 'Standard VAT', 'ภาษีมูลค่าเพิ่มอัตราทั่วไป', 'VAT', 'flat_rate', true, 'Applied to the invoice subtotal. Statutory rate is 10%; reduced to 7% (incl. local tax) by Royal Decree, renewed yearly.', 0),
	(2, 'TH', 'VAT_ZERO', 'Zero-rated VAT (exports)', 'ภาษีมูลค่าเพิ่มอัตราร้อยละ 0', 'VAT', 'flat_rate', false, 'Export of goods and qualifying services.', 1),
	(3, 'TH', 'WHT_PND3_53', 'Withholding tax on payments (PND3 individuals / PND53 companies)', 'ภาษีหัก ณ ที่จ่าย ภ.ง.ด.3 / ภ.ง.ด.53', 'WHT', 'rate_by_category', true, 'Rate depends on the income type of the payment. Base is the amount before VAT.', 2),
	(4, 'TH', 'WHT_MIN_THRESHOLD', 'Minimum payment subject to WHT', 'ยอดขั้นต่ำที่ต้องหักภาษี ณ ที่จ่าย', 'WHT', 'threshold', false, 'No withholding on a single payment below this amount (before VAT).', 3),
	(5, 'TH', 'SSO', 'Social security contribution (Section 33)', 'เงินสมทบประกันสังคม มาตรา 33', 'SSO', 'rate_with_cap', true, 'Employee and employer each pay the same amount. Base = monthly wage clamped to [base_floor, base_cap].', 4),
	(6, 'TH', 'PIT_BRACKETS', 'Personal income tax brackets', 'อัตราภาษีเงินได้บุคคลธรรมดา (ขั้นบันได)', 'PIT', 'bracket_table', true, 'Progressive rates on annual net taxable income.', 5),
	(7, 'TH', 'PIT_EXPENSE', 'Employment income expense deduction', 'ค่าใช้จ่ายเงินได้ 40(1)(2)', 'PIT', 'rate_with_cap', true, '50% of annual employment income, capped.', 6),
	(8, 'TH', 'PIT_ALLOW_PERSONAL', 'Personal allowance', 'ค่าลดหย่อนส่วนตัว', 'PIT', 'fixed_amount', true, NULL, 7),
	(9, 'TH', 'PIT_ALLOW_SPOUSE', 'Spouse allowance (spouse without income)', 'ค่าลดหย่อนคู่สมรส', 'PIT', 'fixed_amount', false, NULL, 8),
	(10, 'TH', 'PIT_ALLOW_CHILD', 'Child allowance', 'ค่าลดหย่อนบุตร', 'PIT', 'fixed_amount', false, 'Simplified: flat amount per child. The higher amount for a 2nd+ child born from 2018 is a candidate for a new version.', 9),
	(11, 'TH', 'PIT_ALLOW_PARENT', 'Parent care allowance', 'ค่าลดหย่อนบิดามารดา', 'PIT', 'fixed_amount', false, 'Per qualifying parent (own and spouse''s parents), aged 60+ with low income.', 10),
	(12, 'TH', 'PIT_ALLOW_LIFE_INS', 'Life insurance premium allowance', 'ค่าลดหย่อนเบี้ยประกันชีวิต', 'PIT', 'fixed_amount', false, 'Employee claims the premium paid; allowance = min(claimed, amount).', 11),
	(13, 'TH', 'PND1_MONTHLY', 'Monthly salary withholding (PND1)', 'ภาษีเงินเดือนหัก ณ ที่จ่ายรายเดือน (ภ.ง.ด.1)', 'PIT', 'formula', true, 'Estimate annual tax from the current monthly income, subtract tax already withheld this year, spread over the remaining months.', 12);


